package au.aumanet.app;
import org.json.*;
/** Exact GroupSession preflight and send helper with declared authenticated Peer objects. */
public final class GroupFirmwareMaintenanceTest {
 static int assertions;static void check(boolean value){assertions++;if(!value)throw new AssertionError("Legacy maintenance capability regression #"+assertions);}
 public static void main(String[]args)throws Exception{JSONObject legacy=new JSONObject().put("name","Legacy").put("token","").put("messageVersion",2);check(GroupFirmwareMaintenanceCapability.read(legacy.opt("firmwareMaintenanceVersion"))==0);legacy.put("firmwareMaintenanceVersion",1);check(legacy.getString("name").equals("Legacy")&&legacy.getInt("messageVersion")==2);for(Object value:new Object[]{"1",true,2,Double.NaN})check(GroupFirmwareMaintenanceCapability.read(value)==0);check(GroupFirmwareMaintenanceCapability.read(1)==1);GroupFirmwareMaintenanceHarness h=new GroupFirmwareMaintenanceHarness();InternetSharingScope captured=h.scope;JSONObject prepare=new JSONObject().put("action","prepare");check(!h.firmwareMaintenanceSupported(captured));check(!h.sendMaintenance(captured,h.target,prepare,"firmware-maintenance")&&h.peer().sent==0);check(h.sendMaintenance(captured,h.target,prepare,"radio-maintenance")&&h.peer().sent==1);h.peer().firmwareMaintenanceVersion=1;check(h.firmwareMaintenanceSupported(captured));check(h.sendMaintenance(captured,h.target,prepare,"firmware-maintenance")&&h.peer().sent==2);GroupFirmwareMaintenanceHarness.Peer old=h.peer();h.replace(0);check(old.firmwareMaintenanceVersion==1&&!h.firmwareMaintenanceSupported(captured));check(!h.sendMaintenance(captured,h.target,prepare,"firmware-maintenance")&&h.peer().sent==0);h.replace(1);h.peer().closed.set(true);check(!h.firmwareMaintenanceSupported(captured));h.replace(1);h.peer().run=3;check(!h.firmwareMaintenanceSupported(captured));h.member();check(!h.firmwareMaintenanceSupported(h.scope));h.ownerConnection.firmwareMaintenanceVersion=1;check(h.firmwareMaintenanceSupported(h.scope));System.out.println(new JSONObject().put("status","pass").put("testCount",3).put("assertionCount",assertions));}
}
